package com.runevault;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RuneVaultPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(RuneVaultPlugin.class);
        RuneLite.main(args);
    }
}

package com.runevault;

import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.*;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ExecutorServiceExceptionLogger;
import okhttp3.OkHttpClient;

import javax.swing.SwingUtilities;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.inject.Inject;

@Slf4j
@PluginDescriptor(
    name = "Rune Vault",
    description = "Sync your OSRS portfolio — GE trades, item pickups, drops, and bank — to Rune Vault.",
    tags = {"portfolio", "ge", "grand exchange", "tracker", "runevault"}
)
public class RuneVaultPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar clientToolbar;
    @Inject private RuneVaultConfig config;
    @Inject private ItemManager itemManager;
    @Inject private OkHttpClient okHttpClient;
    @Inject private Gson gson;

    private SupabaseClient supabase;
    private RealtimeClient realtime;
    private GETracker geTracker;
    private InventoryTracker inventoryTracker;
    private BankTracker bankTracker;
    private ScheduledExecutorService linkCodePoller;
    private ScheduledFuture<?> linkCodePollerFuture;

    private RuneVaultPanel panel;
    private NavigationButton navButton;

    private final AtomicBoolean isConnecting = new AtomicBoolean(false);
    private volatile String  lastPlayerName        = null;
    private volatile boolean playerNamePending      = false; // resolved on first GameTick
    private volatile boolean shownDisabledWarning   = false; // one-time per session

    // -------------------------------------------------------------------------
    // Lifecycle
    // -------------------------------------------------------------------------

    @Override
    protected void startUp()
    {
        supabase = new SupabaseClient(okHttpClient, gson, config);
        supabase.setOnSessionLost(() -> {
            SwingUtilities.invokeLater(() -> panel.setDisconnected());
            showChatMessage("<col=ff6060>Session expired</col> \u2014 please re-link via the Rune Vault panel.");
        });

        geTracker = new GETracker(supabase, config, itemManager);
        inventoryTracker = new InventoryTracker(supabase, config, itemManager);
        bankTracker = new BankTracker(supabase, config, itemManager, this::showChatMessage, client);

        // Build the side panel. Visibility is read-only here — the app owns is_public
        // and the plugin mirrors it via Realtime + initial fetch.
        panel = new RuneVaultPanel(e -> handlePanelConnect(), e -> handlePanelDisconnect(), config,
            supabase::getCachedShortId);
        // Repaint the badge whenever SupabaseClient updates cachedIsPublic.
        // getProfileIsPublic() returns null for the unknown tri-state — refreshVisibility
        // handles that by showing the neutral "Visibility: —" badge.
        supabase.setOnVisibilityChanged(() -> panel.refreshVisibility(supabase.getProfileIsPublic()));
        navButton = NavigationButton.builder()
            .tooltip("Rune Vault")
            .icon(RuneVaultPanel.buildNavIcon())
            .priority(5)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);

        // Single-thread executor — init runs first, then polling starts
        linkCodePoller = new ExecutorServiceExceptionLogger(Executors.newSingleThreadScheduledExecutor());

        // Now that the executor exists, create and wire up the RealtimeClient.
        // The disconnect callback is dispatched onto linkCodePoller so it runs
        // on the same thread as all other SupabaseClient state mutations.
        realtime = new RealtimeClient(
            okHttpClient, gson, linkCodePoller,
            () -> {
                log.info("[RuneVault] Remote disconnect received via Realtime.");
                SwingUtilities.invokeLater(() -> panel.setDisconnected());
                showChatMessage("Disconnected from Rune Vault via the app.");
                supabase.disconnect();
            },
            // Realtime is_public push from the app → mirror locally; SupabaseClient
            // fires onVisibilityChanged which repaints the panel badge.
            isPublic -> supabase.applyVisibilityFromServer(isPublic)
        );
        supabase.setRealtimeClient(realtime);

        // Run auth init off the EDT (blocking network calls not allowed on EDT)
        linkCodePoller.execute(() -> {
            if (!config.authToken().isEmpty())
            {
                log.info("[RuneVault] Session found — restoring.");
                supabase.initFromStoredToken();
                if (supabase.isAuthenticated())
                {
                    config.setConnectionStatus("Connected \u2713");
                    panel.setConnected(lastPlayerName);
                    // setPluginActive(true) is called inside initFromStoredToken when a
                    // lastProfileId is known, so we don't call it here (avoids activating
                    // the wrong profile before the RS username is resolved).
                    // If the player is not in-game (e.g. on the login/loading screen),
                    // clear plugin_active so the app shows the correct idle state.
                    clientThread.invokeLater(() -> {
                        if (client.getGameState() != GameState.LOGGED_IN)
                        {
                            linkCodePoller.execute(() -> supabase.onPlayerLogout());
                        }
                    });
                    showSyncWarningIfNeeded();
                }
                else
                {
                    panel.setDisconnected();
                }
            }
            else if (!config.linkCode().isEmpty())
            {
                log.info("[RuneVault] Link code detected — connecting to Rune Vault...");
                boolean ok = supabase.exchangeLinkCode(config.linkCode());
                if (ok)
                {
                    log.info("[RuneVault] Linked successfully!");
                    config.setConnectionStatus("Connected \u2713");
                    panel.setConnected(lastPlayerName);
                }
                else
                {
                    log.warn("[RuneVault] Link failed — code may be expired. Generate a new one in the Rune Vault app.");
                    config.setConnectionStatus("Failed \u2014 generate a new code in the app");
                    panel.setFeedback("Failed \u2014 generate a new code in the app", true);
                }
            }
            else
            {
                log.info("[RuneVault] Not linked. Open the Rune Vault app \u2192 Settings \u2192 Connect RuneLite Plugin.");
                config.setConnectionStatus("Not connected");
                panel.setDisconnected();
            }

            // If the player is already in-game when the plugin loads, switch to their profile
            clientThread.invokeLater(() -> {
                if (client.getGameState() == GameState.LOGGED_IN && supabase.isAuthenticated())
                {
                    String playerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
                    if (playerName != null)
                    {
                        lastPlayerName = playerName;
                        panel.updatePlayerName(playerName);
                        final String name = playerName;
                        linkCodePoller.execute(() -> supabase.switchProfileForUsername(name));
                    }
                }
            });
        });

        // Poll every 3s for the Connect checkbox (single-thread executor ensures init completes first)
        linkCodePollerFuture = linkCodePoller.scheduleWithFixedDelay(this::checkLinkCode, 3, 3, TimeUnit.SECONDS);

        // Heartbeat every 2 minutes — keeps plugin_last_seen fresh so the app can
        // distinguish active (online) from crashed (stale) vs disconnected (explicit).
        linkCodePoller.scheduleWithFixedDelay(
            () -> supabase.sendHeartbeat(), 120, 120, TimeUnit.SECONDS);

        // Remote disconnect is now handled by RealtimeClient (WebSocket) instead of polling.
        // checkRemoteDisconnect() is still used by RealtimeClient's one-time REST fallback
        // on reconnect to catch events missed while the socket was down.
    }

    private void checkLinkCode()
    {
        if (!config.connectNow()) return;
        config.setConnectNow(false); // reset checkbox immediately — prevents re-trigger

        String code = config.linkCode().trim();
        if (code.length() != 6)
        {
            config.setConnectionStatus("Error: enter a valid 6-char code");
            showChatMessage("Invalid code \u2014 enter the 6-character code from the Rune Vault app.");
            log.warn("[RuneVault] Connect checked but no valid 6-character code entered.");
            return;
        }
        if (!config.authToken().isEmpty())
        {
            config.setConnectionStatus("Connected \u2713");
            showChatMessage("Already linked to Rune Vault.");
            log.info("[RuneVault] Already linked.");
            return;
        }

        if (!isConnecting.compareAndSet(false, true))
        {
            showChatMessage("Already connecting, please wait\u2026");
            return;
        }

        config.setConnectionStatus("Connecting\u2026");
        showChatMessage("Connecting to Rune Vault\u2026");
        log.info("[RuneVault] Connecting to Rune Vault...");

        boolean ok = supabase.exchangeLinkCode(code);
        isConnecting.set(false);

        if (ok)
        {
            config.setConnectionStatus("Connected \u2713");
            showChatMessage("Linked! Your portfolio will now sync automatically.");
            log.info("[RuneVault] Linked successfully!");
            // Stop polling — successfully linked via checkbox path
            if (linkCodePollerFuture != null) linkCodePollerFuture.cancel(false);
        }
        else
        {
            config.setConnectionStatus("Failed \u2014 generate a new code in the app");
            showChatMessage("Link failed \u2014 code may be expired. Generate a new one in the Rune Vault app.");
            log.warn("[RuneVault] Link failed.");
        }
    }

    private void showChatMessage(String message)
    {
        clientThread.invokeLater(() ->
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=e8a060>[Rune Vault]</col> " + message, null)
        );
    }

    private void showSyncWarningIfNeeded()
    {
        if (config.syncWarningShown()) return;
        config.setSyncWarningShown(true);
        showChatMessage("Your GE trades, inventory pickups/drops, and bank contents will be synced to your Rune Vault account. You can disable any of these in the plugin panel.");
    }

    private void handlePanelConnect()
    {
        if (!isConnecting.compareAndSet(false, true)) return;

        String code = panel.getCode();
        if (code.length() != 6)
        {
            isConnecting.set(false);
            panel.setFeedback("Enter a valid 6-character code", true);
            return;
        }
        if (supabase.isAuthenticated())
        {
            // Already connected — treat as a re-link: disconnect first, then connect
            linkCodePoller.execute(() -> supabase.disconnect());
            panel.setDisconnected();
        }

        panel.setConnecting();
        showChatMessage("Connecting to Rune Vault\u2026");

        linkCodePoller.execute(() -> {
            boolean ok = supabase.exchangeLinkCode(code);
            isConnecting.set(false);
            if (ok)
            {
                config.setConnectionStatus("Connected \u2713");
                shownDisabledWarning = false;
                panel.setConnected(lastPlayerName);
                showChatMessage("Linked! Your portfolio will now sync automatically.");
                showSyncWarningIfNeeded();
                log.info("[RuneVault] Linked successfully via panel.");
                // Stop the link-code checkbox poller — no longer needed after successful link
                if (linkCodePollerFuture != null) linkCodePollerFuture.cancel(false);
                // If the player is currently in-game, switch profile immediately.
                // Use clientThread to safely read game state, then dispatch to linkCodePoller.
                // Guard against stale lastPlayerName from a previous login session.
                clientThread.invokeLater(() -> {
                    if (client.getGameState() == GameState.LOGGED_IN && lastPlayerName != null)
                    {
                        final String name = lastPlayerName;
                        linkCodePoller.execute(() -> supabase.switchProfileForUsername(name));
                    }
                });
            }
            else
            {
                panel.setFeedback("Failed \u2014 code may be expired", true);
                config.setConnectionStatus("Failed \u2014 generate a new code in the app");
                showChatMessage("Link failed \u2014 code may be expired. Generate a new one in the Rune Vault app.");
                log.warn("[RuneVault] Link failed via panel.");
            }
        });
    }

    private void handlePanelDisconnect()
    {
        isConnecting.set(false);
        // Don't clear lastPlayerName — the player is still logged in, only the auth changed.
        // It will be reused immediately if the user reconnects without logging out.
        panel.setDisconnected();
        showChatMessage("Disconnected from Rune Vault.");
        log.info("[RuneVault] Disconnected via panel.");
        // Run setPluginActive(false) + credential wipe off the EDT to avoid blocking Swing
        linkCodePoller.execute(() -> supabase.disconnect());
    }

    @Override
    protected void shutDown()
    {
        // Close the Realtime WebSocket immediately — no more reconnects after shutdown.
        // Must happen before the executor shuts down (RealtimeClient uses it for scheduling).
        if (realtime != null)
        {
            realtime.close();
            realtime = null;
        }

        // Submit setPluginActive(false) to the executor before shutting it down so the
        // HTTP call runs off the EDT. setPluginActive is synchronous, so awaitTermination
        // (bounded) blocks long enough for the PATCH to land. Without the await, shutdown()
        // returns immediately and RuneLite can kill the JVM before the call dispatches —
        // the app keeps showing "active" until the heartbeat staleness timer (10 min) trips.
        if (supabase != null && linkCodePoller != null)
            linkCodePoller.execute(() -> supabase.setPluginActive(false));

        if (linkCodePoller != null)
        {
            linkCodePoller.shutdown();
            try {
                linkCodePoller.awaitTermination(2, TimeUnit.SECONDS);
            } catch (InterruptedException ignored) {
                // RuneLite is tearing us down; best-effort is fine.
            }
            linkCodePoller = null;
        }
        if (navButton != null)
        {
            clientToolbar.removeNavigation(navButton);
            navButton = null;
        }
    }

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            // Fresh baseline on each login
            inventoryTracker.reset();
            // Defer player name lookup — getName() is null at this exact moment.
            // onGameTick will resolve it on the first tick.
            playerNamePending = true;
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN
              || event.getGameState() == GameState.LOADING
              || event.getGameState() == GameState.CONNECTION_LOST)
        {
            geTracker.reset();
            playerNamePending = false;
            if (event.getGameState() == GameState.LOGIN_SCREEN
             || event.getGameState() == GameState.CONNECTION_LOST)
            {
                lastPlayerName = null; // reset so the connected message shows on next genuine login
            }
            if (supabase.isAuthenticated())
            {
                // Player logged out, is on the loading/connecting screen, or lost connection —
                // turn off the green dot in the app and stop heartbeats until they fully log in.
                // Clear equipped items (they're ephemeral — player is no longer wearing them).
                // Profile will be re-resolved when they log in again via switchProfileForUsername.
                linkCodePoller.execute(() -> {
                    supabase.clearEquipmentItems();
                    supabase.onPlayerLogout();
                });
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        // Let BankTracker detect when the bank widget closes so it can allow the next genuine open
        bankTracker.checkBankClosed(client);

        if (!playerNamePending) return;
        String playerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
        if (playerName == null) return; // still loading — try again next tick

        playerNamePending = false;
        boolean isNewLogin = !playerName.equals(lastPlayerName);
        lastPlayerName = playerName;
        panel.updatePlayerName(playerName);

        if (!config.authToken().isEmpty())
        {
            final String name = playerName;
            // Only show the connected message on a genuine login, not on instance/area changes
            if (isNewLogin)
            {
                showChatMessage("<col=00c060>Connected</col> as <col=e8a060>" + name + "</col> \u2014 syncing to Rune Vault.");
            }
            // switchProfileForUsername calls ensureAuthenticated() internally — token refresh
            // is handled there, so we only need to confirm credentials exist at all.
            linkCodePoller.execute(() -> supabase.switchProfileForUsername(name));
        }
    }

    @Subscribe
    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
    {
        if (!supabase.isAuthenticated())
        {
            // Warn the player once per session when a completed trade can't be synced
            GrandExchangeOfferState state = event.getOffer().getState();
            if (!shownDisabledWarning
                && (state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.SOLD))
            {
                shownDisabledWarning = true;
                showChatMessage("<col=ff6060>Not connected</col> \u2014 this trade won\u2019t be synced. "
                    + "Open the Rune Vault panel to link your account.");
            }
            return;
        }
        geTracker.onOfferChanged(event);
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (!supabase.isAuthenticated()) return;
        inventoryTracker.onItemContainerChanged(event);
        bankTracker.onItemContainerChanged(event);
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!supabase.isAuthenticated()) return;
        inventoryTracker.onMenuOptionClicked(event);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"runevault".equals(event.getGroup())) return;
        // Keep the side panel toggles in sync when a setting is changed via the config panel
        panel.refreshToggles(config);
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (!supabase.isAuthenticated()) return;
        bankTracker.onWidgetLoaded(event);
    }

    // -------------------------------------------------------------------------
    // Config
    // -------------------------------------------------------------------------

    @Provides
    RuneVaultConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RuneVaultConfig.class);
    }
}

package com.runevault;

/**
 * Build-time constants for the Rune Vault plugin.
 *
 * SUPABASE_ANON_KEY is the Supabase anonymous (public) key. It is intentionally
 * committed here — it is designed to be client-facing and is compiled into every
 * user's installed JAR, the same as it would be in a mobile or web app.
 * Row-Level Security on the Supabase project enforces access control.
 */
public final class RuneVaultBuildConfig
{
    public static final String SUPABASE_URL      = "https://lxpbozteorpijrowhubl.supabase.co";
    public static final String SUPABASE_ANON_KEY = "sb_publishable__K0u7EoZTfXWZQyNwSF55g_XI0R4vZB";

    private RuneVaultBuildConfig() {}
}

package com.runevault;

import lombok.extern.slf4j.Slf4j;
import okhttp3.*;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;

/**
 * Manages a persistent Supabase Realtime WebSocket connection for the RuneVault plugin.
 *
 * Subscribes to UPDATE events on the profiles table filtered by user_id.
 * When plugin_disconnect_requested=true is received, fires onDisconnectRequested
 * on the provided executor (never on the OkHttp WebSocket thread).
 *
 * Handles:
 *  - Phoenix protocol framing (join, heartbeat, postgres_changes)
 *  - Exponential reconnect backoff (2s → 5s → 10s → 30s → 60s, capped)
 *  - One-time REST fallback on reconnect to catch events missed while down
 *  - In-band token refresh (sends updated access_token to server without reconnecting)
 *  - Duplicate connection guard (synchronized on currentSocket)
 *  - Clean shutdown with no dangling threads
 */
@Slf4j
public class RealtimeClient
{
    private static final String WS_URL_TEMPLATE =
        RuneVaultBuildConfig.SUPABASE_URL.replace("https://", "wss://") + "/realtime/v1/websocket?apikey=%s&vsn=1.0.0";
    private static final String ANON_KEY =
        RuneVaultBuildConfig.SUPABASE_ANON_KEY;
    private static final String SUPABASE_URL =
        RuneVaultBuildConfig.SUPABASE_URL;

    // Phoenix heartbeat interval — server drops the connection after ~60s without one
    private static final long PHOENIX_HEARTBEAT_INTERVAL_S = 25;

    // Reconnect backoff steps in seconds
    private static final long[] BACKOFF_STEPS = { 2, 5, 10, 30, 60 };

    private final OkHttpClient httpClient;
    private final Gson         gson;
    private final ScheduledExecutorService executor; // shared with SupabaseClient — single-thread
    private final Runnable onDisconnectRequested;     // dispatched to executor, never WS thread
    private final Consumer<Boolean> onVisibilityChanged; // dispatched to executor on is_public UPDATE

    // Guarded by `this` lock
    private WebSocket  currentSocket    = null;
    private boolean    closed           = false; // true after close() — suppresses reconnects
    private String     currentUserId    = null;
    private String     currentToken     = null;

    private final AtomicInteger  ref           = new AtomicInteger(1);
    private final AtomicInteger  backoffIndex  = new AtomicInteger(0);
    private       ScheduledFuture<?> phoenixHeartbeat = null;
    private       ScheduledFuture<?> reconnectFuture  = null;

    public RealtimeClient(
        OkHttpClient httpClient,
        Gson gson,
        ScheduledExecutorService executor,
        Runnable onDisconnectRequested,
        Consumer<Boolean> onVisibilityChanged)
    {
        this.httpClient            = httpClient;
        this.gson                  = gson;
        this.executor              = executor;
        this.onDisconnectRequested = onDisconnectRequested;
        this.onVisibilityChanged   = onVisibilityChanged;
    }

    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    /**
     * Open a Realtime subscription for the given user.
     * Safe to call multiple times — closes any existing socket first.
     * Must be called from the executor thread (already the pattern in SupabaseClient).
     */
    public synchronized void connect(String userId, String accessToken)
    {
        // Reset closed so re-linking after a user disconnect reopens the socket.
        // closed=true is only permanent during plugin shutdown (shutDown() path);
        // a user disconnect + re-link must be able to reconnect.
        closed        = false;
        currentUserId = userId;
        currentToken  = accessToken;
        openSocket();
    }

    /**
     * Update the access token in-band after a token refresh.
     * Sends a Phoenix leave + rejoin with the new token — no TCP reconnect needed.
     * Falls back to a full reconnect if the socket is gone.
     */
    public synchronized void updateToken(String newToken)
    {
        currentToken = newToken;
        if (currentSocket == null || currentUserId == null) return;

        log.debug("[RuneVault/Realtime] Updating access token in-band.");
        // Leave the current channel
        currentSocket.send(buildLeave());
        // Rejoin with the new token — server will accept the updated credentials
        currentSocket.send(buildJoin(currentUserId, newToken));
    }

    /**
     * Permanently close the WebSocket. Suppresses all reconnect attempts.
     * Must be called on plugin shutdown.
     */
    public synchronized void close()
    {
        closed = true;
        cancelPhoenixHeartbeat();
        cancelReconnect();
        if (currentSocket != null)
        {
            currentSocket.cancel(); // hard close — don't wait for server ack
            currentSocket = null;
        }
        log.debug("[RuneVault/Realtime] Closed.");
    }

    // -------------------------------------------------------------------------
    // Internal — socket lifecycle
    // -------------------------------------------------------------------------

    private void openSocket()
    {
        // Cancel any pending reconnect — we're connecting now
        cancelReconnect();

        // Hard-cancel any existing socket before opening a new one
        if (currentSocket != null)
        {
            currentSocket.cancel();
            currentSocket = null;
        }

        String url = String.format(WS_URL_TEMPLATE, ANON_KEY);
        Request request = new Request.Builder().url(url).build();
        currentSocket = httpClient.newWebSocket(request, new Listener());
        log.debug("[RuneVault/Realtime] Opening WebSocket...");
    }

    private void scheduleReconnect()
    {
        if (closed) return;
        int idx  = Math.min(backoffIndex.getAndIncrement(), BACKOFF_STEPS.length - 1);
        long delay = BACKOFF_STEPS[idx];
        log.debug("[RuneVault/Realtime] Reconnecting in {}s (attempt {}).", delay, idx + 1);
        reconnectFuture = executor.schedule(() -> {
            synchronized (RealtimeClient.this)
            {
                if (!closed && currentUserId != null && currentToken != null)
                    openSocket();
            }
        }, delay, TimeUnit.SECONDS);
    }

    private void cancelPhoenixHeartbeat()
    {
        if (phoenixHeartbeat != null) { phoenixHeartbeat.cancel(false); phoenixHeartbeat = null; }
    }

    private void cancelReconnect()
    {
        if (reconnectFuture != null) { reconnectFuture.cancel(false); reconnectFuture = null; }
    }

    private void startPhoenixHeartbeat(WebSocket socket)
    {
        cancelPhoenixHeartbeat();
        phoenixHeartbeat = executor.scheduleWithFixedDelay(() -> {
            synchronized (RealtimeClient.this)
            {
                if (currentSocket == socket) // only heartbeat if this is still the live socket
                    socket.send(buildHeartbeat());
            }
        }, PHOENIX_HEARTBEAT_INTERVAL_S, PHOENIX_HEARTBEAT_INTERVAL_S, TimeUnit.SECONDS);
    }

    // -------------------------------------------------------------------------
    // Internal — one-time REST fallback on reconnect
    // -------------------------------------------------------------------------

    /**
     * Called once after a successful channel join.
     * Checks whether plugin_disconnect_requested was set while the WebSocket was down.
     * This covers the gap between a network drop and the next successful connection.
     */
    private void checkMissedDisconnect()
    {
        if (currentUserId == null || currentToken == null) return;

        Request request = new Request.Builder()
            .url(SUPABASE_URL + "/rest/v1/profiles"
                + "?user_id=eq." + currentUserId
                + "&select=plugin_disconnect_requested")
            .get()
            .addHeader("apikey",        ANON_KEY)
            .addHeader("Authorization", "Bearer " + currentToken)
            .addHeader("Accept",        "application/json")
            .build();

        httpClient.newCall(request).enqueue(new okhttp3.Callback()
        {
            @Override
            public void onFailure(Call call, java.io.IOException e)
            {
                log.debug("[RuneVault/Realtime] Missed-disconnect check failed: {}", e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws java.io.IOException
            {
                try {
                    if (!response.isSuccessful() || response.body() == null) return;
                    String body = response.body().string();
                    com.google.gson.JsonArray arr =
                        new JsonParser().parse(body).getAsJsonArray();
                    for (int i = 0; i < arr.size(); i++)
                    {
                        JsonObject row = arr.get(i).getAsJsonObject();
                        if (row.has("plugin_disconnect_requested")
                                && row.get("plugin_disconnect_requested").getAsBoolean())
                        {
                            log.debug("[RuneVault/Realtime] Missed disconnect detected via REST fallback.");
                            executor.execute(onDisconnectRequested);
                            return;
                        }
                    }
                } finally {
                    response.close();
                }
            }
        });
    }

    // -------------------------------------------------------------------------
    // Internal — Phoenix message builders
    // -------------------------------------------------------------------------

    private String buildJoin(String userId, String accessToken)
    {
        JsonObject config = new JsonObject();
        com.google.gson.JsonArray changes = new com.google.gson.JsonArray();
        JsonObject filter = new JsonObject();
        filter.addProperty("event",  "UPDATE");
        filter.addProperty("schema", "public");
        filter.addProperty("table",  "profiles");
        filter.addProperty("filter", "user_id=eq." + userId);
        changes.add(filter);
        config.add("postgres_changes", changes);

        JsonObject payload = new JsonObject();
        payload.add("config", config);
        payload.addProperty("access_token", accessToken);

        JsonObject msg = new JsonObject();
        msg.addProperty("event",   "phx_join");
        msg.addProperty("topic",   "realtime:db-changes");
        msg.add("payload",         payload);
        msg.addProperty("ref",     String.valueOf(ref.getAndIncrement()));
        return gson.toJson(msg);
    }

    private String buildLeave()
    {
        JsonObject msg = new JsonObject();
        msg.addProperty("event",   "phx_leave");
        msg.addProperty("topic",   "realtime:db-changes");
        msg.add("payload",         new JsonObject());
        msg.addProperty("ref",     String.valueOf(ref.getAndIncrement()));
        return gson.toJson(msg);
    }

    private String buildHeartbeat()
    {
        JsonObject msg = new JsonObject();
        msg.addProperty("event",   "heartbeat");
        msg.addProperty("topic",   "phoenix");
        msg.add("payload",         new JsonObject());
        msg.addProperty("ref",     String.valueOf(ref.getAndIncrement()));
        return gson.toJson(msg);
    }

    // -------------------------------------------------------------------------
    // WebSocketListener
    // -------------------------------------------------------------------------

    private class Listener extends WebSocketListener
    {
        @Override
        public void onOpen(WebSocket webSocket, Response response)
        {
            log.debug("[RuneVault/Realtime] WebSocket opened. Joining channel...");
            synchronized (RealtimeClient.this)
            {
                if (currentUserId != null && currentToken != null)
                    webSocket.send(buildJoin(currentUserId, currentToken));
                startPhoenixHeartbeat(webSocket);
            }
        }

        @Override
        public void onMessage(WebSocket webSocket, String text)
        {
            try
            {
                JsonObject msg     = new JsonParser().parse(text).getAsJsonObject();
                String     event   = msg.has("event")   ? msg.get("event").getAsString()   : "";
                String     topic   = msg.has("topic")   ? msg.get("topic").getAsString()   : "";
                JsonObject payload = msg.has("payload") ? msg.get("payload").getAsJsonObject() : new JsonObject();

                switch (event)
                {
                    case "phx_reply":
                        // Server ack on join — check status
                        if ("realtime:db-changes".equals(topic))
                        {
                            String status = payload.has("status")
                                ? payload.get("status").getAsString() : "";
                            if ("ok".equals(status))
                            {
                                log.debug("[RuneVault/Realtime] Channel joined successfully.");
                                backoffIndex.set(0); // reset backoff on successful join
                                // Check for disconnect events we missed while the socket was down
                                checkMissedDisconnect();
                            }
                            else
                            {
                                log.debug("[RuneVault/Realtime] Channel join failed: {}", payload);
                                // Token may be stale — SupabaseClient will refresh and call updateToken()
                            }
                        }
                        break;

                    case "postgres_changes":
                        // A profile row was updated — check if it's a disconnect request
                        handlePostgresChange(payload);
                        break;

                    case "phx_error":
                        log.debug("[RuneVault/Realtime] Phoenix error: {}", payload);
                        break;

                    case "phx_close":
                        log.debug("[RuneVault/Realtime] Phoenix closed channel.");
                        break;

                    default:
                        // heartbeat replies, system messages — ignore
                        break;
                }
            }
            catch (Exception e)
            {
                log.debug("[RuneVault/Realtime] Error parsing message: {}", e.getMessage());
            }
        }

        @Override
        public void onClosing(WebSocket webSocket, int code, String reason)
        {
            log.debug("[RuneVault/Realtime] WebSocket closing: {} {}", code, reason);
            webSocket.close(1000, null);
        }

        @Override
        public void onClosed(WebSocket webSocket, int code, String reason)
        {
            log.debug("[RuneVault/Realtime] WebSocket closed: {} {}", code, reason);
            handleSocketGone(webSocket);
        }

        @Override
        public void onFailure(WebSocket webSocket, Throwable t, Response response)
        {
            log.debug("[RuneVault/Realtime] WebSocket failure: {}", t.getMessage());
            handleSocketGone(webSocket);
        }
    }

    // -------------------------------------------------------------------------
    // Internal — message handling & reconnect
    // -------------------------------------------------------------------------

    private void handlePostgresChange(JsonObject payload)
    {
        try
        {
            // Payload structure: { data: { type, table, record: { plugin_disconnect_requested, is_public, ... } } }
            if (!payload.has("data")) return;
            JsonObject data = payload.getAsJsonObject("data");
            if (!data.has("record")) return;
            JsonObject record = data.getAsJsonObject("record");

            // Disconnect signal — fires only when set to true
            if (record.has("plugin_disconnect_requested")
                    && !record.get("plugin_disconnect_requested").isJsonNull()
                    && record.get("plugin_disconnect_requested").getAsBoolean())
            {
                log.debug("[RuneVault/Realtime] Disconnect requested via Realtime.");
                // Dispatch to executor — never mutate plugin state from the OkHttp WS thread
                executor.execute(onDisconnectRequested);
            }

            // Visibility — app is the single source of truth; plugin mirrors it.
            // Always dispatch on every UPDATE; SupabaseClient short-circuits no-op changes.
            if (onVisibilityChanged != null
                    && record.has("is_public")
                    && !record.get("is_public").isJsonNull())
            {
                final boolean isPublic = record.get("is_public").getAsBoolean();
                executor.execute(() -> onVisibilityChanged.accept(isPublic));
            }
        }
        catch (Exception e)
        {
            log.debug("[RuneVault/Realtime] Error handling postgres_changes: {}", e.getMessage());
        }
    }

    private synchronized void handleSocketGone(WebSocket socket)
    {
        // Only act on the socket we currently own — stale callbacks from old sockets are ignored
        if (socket != currentSocket) return;
        currentSocket = null;
        cancelPhoenixHeartbeat();
        if (!closed) scheduleReconnect();
    }
}

package com.runevault;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.game.ItemManager;

import javax.swing.*;
import java.awt.Frame;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

@Slf4j
public class BankTracker
{
    // RuneLite widget group ID for the bank interface
    public static final int BANK_WIDGET_GROUP_ID = 12;
    private static final int COINS_ID = 995;

    private final SupabaseClient supabase;
    private final RuneVaultConfig config;
    private final ItemManager itemManager;
    private final Consumer<String> chatMessage;
    private final Client client;

    // Becomes true once the bank container fires after the bank widget loads
    private boolean bankOpenPending = false;

    // True after the first scan this bank-open session.
    // Prevents bank tab switches (which re-fire WidgetLoaded for group 12) from triggering
    // a second scan with only the filtered tab's items visible.
    // Reset by checkBankClosed() when the bank widget disappears.
    private boolean bankScannedThisOpen = false;

    // Number of consecutive game ticks that the bank widget has been absent.
    // Requires 2+ consecutive null ticks before treating it as a real close — tab
    // transitions briefly destroy the widget for 1 tick, which would otherwise
    // erroneously reset bankScannedThisOpen and allow a second scan mid-session.
    private int bankClosedTickCount = 0;

    // Monotonically-increasing counter incremented on every syncItems() call.
    // The removeItemsMissingFromBank callback captures the value at dispatch time
    // and only executes if no newer scan has started — prevents stale callbacks
    // from deleting rows that a later scan just upserted.
    private volatile int bankScanGeneration = 0;

    // Most recent inventory coin balance — kept in sync so we can add it to bank coins on scan
    private int cachedInventoryCoins = 0;

    public BankTracker(SupabaseClient supabase, RuneVaultConfig config, ItemManager itemManager, Consumer<String> chatMessage, Client client)
    {
        this.supabase = supabase;
        this.config = config;
        this.itemManager = itemManager;
        this.chatMessage = chatMessage;
        this.client = client;
    }

    /**
     * Called from RuneVaultPlugin.onGameTick so BankTracker can detect when the bank
     * widget closes (widget returns null) and reset the scan-guard for the next open.
     */
    public void checkBankClosed(net.runelite.api.Client client)
    {
        if (!bankScannedThisOpen)
        {
            bankClosedTickCount = 0;
            return;
        }
        if (client.getWidget(BANK_WIDGET_GROUP_ID, 0) == null)
        {
            bankClosedTickCount++;
            if (bankClosedTickCount >= 2)
            {
                log.debug("[RuneVault] Bank closed — resetting scan guard (closedTicks={})", bankClosedTickCount);
                bankScannedThisOpen = false;
                bankOpenPending     = false;
                bankClosedTickCount = 0;
            }
        }
        else
        {
            // Widget visible again — was just a tab transition, not a real close
            bankClosedTickCount = 0;
        }
    }

    public void onWidgetLoaded(WidgetLoaded event)
    {
        log.debug("[RuneVault] onWidgetLoaded groupId={} bankScanEnabled={} scannedThisOpen={}",
            event.getGroupId(), config.bankScanEnabled(), bankScannedThisOpen);
        if (!config.bankScanEnabled()) return;
        if (!supabase.isAuthenticated()) return;
        if (event.getGroupId() == BANK_WIDGET_GROUP_ID)
        {
            if (bankScannedThisOpen)
            {
                // Tab switch or widget refresh — ignore to prevent partial re-scan
                log.debug("[RuneVault] Bank WidgetLoaded ignored — already scanned this open session (tab switch?)");
                return;
            }
            log.debug("[RuneVault] Bank widget detected — setting bankOpenPending=true");
            bankOpenPending = true;
        }
    }

    /**
     * Fires when a container changes. We wait for the bank container after the
     * bank widget loads to ensure all items are populated.
     */
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        // Always keep inventory coin cache up to date
        if (event.getContainerId() == InventoryID.INVENTORY.getId())
        {
            ItemContainer inv = event.getItemContainer();
            if (inv != null) cachedInventoryCoins = getCoins(inv);
        }

        if (!config.bankScanEnabled()) return;
        log.debug("[RuneVault] onItemContainerChanged containerId={} bankOpenPending={} bankId={}",
            event.getContainerId(), bankOpenPending, InventoryID.BANK.getId());
        if (!bankOpenPending) return;
        if (event.getContainerId() != InventoryID.BANK.getId()) return;

        // In modern OSRS the bank sends ALL items to the client on open regardless of which
        // tab is displayed — tabs are purely a visual filter on the client side.
        // No need to enforce tab 0; scan immediately on the first container event.
        bankOpenPending     = false;
        bankScannedThisOpen = true; // block re-scans until bank closes

        ItemContainer container = event.getItemContainer();
        if (container == null) return;

        ScanResult result = buildItemList(container);
        int bankCoins = getCoins(container);
        log.debug("[RuneVault] Bank scan: {} items, {} placeholders skipped, {} coins",
            result.items.size(), result.placeholderCount, bankCoins);
        if (result.items.isEmpty() && bankCoins == 0) return;

        if (config.bankScanMode() == BankScanMode.AUTO)
        {
            syncItems(result, bankCoins);
        }
        else
        {
            promptUser(result, bankCoins);
        }
    }

    private void promptUser(ScanResult result, int bankCoins)
    {
        SwingUtilities.invokeLater(() ->
        {
            int totalSlots = result.items.size() + (bankCoins > 0 ? 1 : 0);
            String placeholderLine = result.placeholderCount > 0
                ? "<br>(" + result.placeholderCount + " placeholder slot(s) skipped)"
                : "";

            JLabel messageLabel = new JLabel("<html><body style='width:360px;font-size:13pt;font-weight:bold'>"
                + "Sync " + totalSlots + " bank slot(s) to Rune Vault?"
                + placeholderLine
                + "</body></html>");

            JCheckBox autoCheckbox = new JCheckBox("<html><body style='width:340px;font-size:11pt'>"
                + "Switch to Auto mode <span style='color:gray'>(recommended — syncs automatically on every bank open)</span>"
                + "</body></html>");

            JButton yesButton = new JButton("Yes");
            JButton noButton  = new JButton("No");

            JPanel buttonPanel = new JPanel();
            buttonPanel.add(yesButton);
            buttonPanel.add(noButton);

            JPanel content = new JPanel();
            content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
            content.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
            content.add(messageLabel);
            content.add(Box.createVerticalStrut(12));
            content.add(autoCheckbox);
            content.add(Box.createVerticalStrut(8));
            content.add(buttonPanel);

            JDialog dialog = new JDialog((Frame) null, "Rune Vault — Bank Scan", false);
            dialog.setContentPane(content);
            dialog.pack();
            dialog.setLocationRelativeTo(null);
            dialog.setAlwaysOnTop(true);
            dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);

            yesButton.addActionListener(e -> {
                dialog.dispose();
                if (autoCheckbox.isSelected()) config.setBankScanMode(BankScanMode.AUTO);
                syncItems(result, bankCoins);
            });
            noButton.addActionListener(e -> dialog.dispose());

            dialog.setVisible(true);
        });
    }

    private void syncItems(ScanResult result, int bankCoins)
    {
        if (!supabase.isProfileReady())
        {
            // Reset the scan guard so the player can close and reopen the bank to retry
            // once profile resolution completes (usually within 1-2s of login).
            bankScannedThisOpen = false;
            log.warn("[RuneVault] Bank sync skipped — profile not yet confirmed for this character.");
            chatMessage.accept("<col=ff6060>Bank sync skipped</col> \u2014 still loading your character. Close and reopen the bank to sync.");
            return;
        }

        // Increment generation so any in-flight callback from a previous scan
        // knows it is stale and should not delete rows from the new scan.
        final int thisGeneration = ++bankScanGeneration;

        log.debug("[RuneVault] Syncing {} bank items ({} placeholders skipped) gen={}",
            result.items.size(), result.placeholderCount, thisGeneration);

        // Build the ID set before the async call so it's captured in the lambda below.
        final java.util.Set<Integer> bankItemIds = new java.util.HashSet<>();
        for (PortfolioItem item : result.items) bankItemIds.add(item.getItemId());

        // Chain removeItemsMissingFromBank as the upsert's onSuccess callback so it only
        // runs AFTER the upsert has landed in the DB — prevents the race where deletes
        // fire before inserts complete and cause items to temporarily vanish in the app.
        // Guard with the generation counter: if a newer scan has already started by the
        // time this callback fires, skip the delete to avoid wiping the new scan's rows.
        Runnable afterUpsert = config.bankRemoveMissing()
            ? () -> {
                if (bankScanGeneration != thisGeneration)
                {
                    log.debug("[RuneVault] Skipping stale removeItemsMissingFromBank (gen {} superseded by gen {})",
                        thisGeneration, bankScanGeneration);
                    return;
                }
                supabase.removeItemsMissingFromBank(bankItemIds);
              }
            : null;
        supabase.bulkUpsertItems(result.items, "runelite", afterUpsert);

        if (config.syncCash())
        {
            long totalCoins = (long) bankCoins + cachedInventoryCoins;
            if (totalCoins > 0) supabase.updateCash(totalCoins);
        }

        int synced = result.items.size() + (bankCoins > 0 ? 1 : 0);
        String skipped = result.placeholderCount > 0 ? " (" + result.placeholderCount + " placeholders skipped)" : "";
        chatMessage.accept("<col=00c060>Bank synced:</col> " + synced + " slot(s)." + skipped);
    }

    /**
     * Builds the list of real items from the bank container.
     * - Skips coins, empty slots, and placeholder slots.
     * - Aggregates quantities across multiple slots of the same item
     *   (e.g. two Fire cape slots → quantity 2, split bolt stacks → summed).
     */
    private ScanResult buildItemList(ItemContainer container)
    {
        // LinkedHashMap preserves insertion order and accumulates quantity per canonical ID
        Map<Integer, PortfolioItem> byId = new LinkedHashMap<>();
        int placeholderCount = 0;
        int emptyCount = 0;
        int coinsCount = 0;

        for (Item item : container.getItems())
        {
            if (item.getId() <= 0) { emptyCount++; continue; }
            if (item.getId() == COINS_ID) { coinsCount++; continue; }
            if (item.getQuantity() <= 0)
            {
                log.debug("[RuneVault][BankSkip] reason=qty<=0  rawId={} qty={} name={}",
                    item.getId(), item.getQuantity(), itemManager.getItemComposition(item.getId()).getName());
                continue;
            }

            // Placeholders report quantity=1 but the item is not actually owned.
            // getPlaceholderTemplateId() returns 0 for real items, >0 for placeholders.
            int placeholderTemplateId = itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId();
            if (placeholderTemplateId > 0)
            {
                log.debug("[RuneVault][BankSkip] reason=placeholder  rawId={} qty={} name={} templateId={}",
                    item.getId(), item.getQuantity(), itemManager.getItemComposition(item.getId()).getName(), placeholderTemplateId);
                placeholderCount++;
                continue;
            }

            // Store each item under its canonical ID (noted → unnoted) so every distinct
            // bank slot gets its own row, matching how the OSRS bank itself shows items.
            int canonicalId = itemManager.canonicalize(item.getId());
            if (canonicalId <= 0) continue;

            String rawName = itemManager.getItemComposition(item.getId()).getName();

            PortfolioItem existing = byId.get(canonicalId);
            if (existing != null)
            {
                // Same canonical ID across multiple slots (noted + unnoted, split stack) — merge.
                byId.put(canonicalId, new PortfolioItem(
                    canonicalId,
                    existing.getItemName(),
                    existing.getQuantity() + item.getQuantity(),
                    existing.getBuyPrice(),
                    existing.getImageUrl(),
                    existing.getHaPrice()
                ));
            }
            else
            {
                int[] prices    = PriceUtil.resolvePrices(canonicalId, itemManager);
                int buyPrice    = prices[0];
                int haPrice     = prices[1];
                String nameLower = rawName.toLowerCase();
                String name      = nameLower.endsWith(" (members)") ? rawName.substring(0, rawName.length() - 10) : rawName;
                String imageUrl  = "https://static.runelite.net/cache/item/icon/" + canonicalId + ".png";
                byId.put(canonicalId, new PortfolioItem(canonicalId, name, item.getQuantity(), buyPrice, imageUrl, haPrice));
            }
        }

        log.debug("[RuneVault][BankScan] done: {} items, {} placeholders, {} empty, {} coin slots",
            byId.size(), placeholderCount, emptyCount, coinsCount);

        return new ScanResult(new ArrayList<>(byId.values()), placeholderCount);
    }

    private int getCoins(ItemContainer container)
    {
        for (Item item : container.getItems())
        {
            if (item.getId() == COINS_ID) return item.getQuantity();
        }
        return 0;
    }

    /** Holds the result of a bank scan: real items + how many placeholders were skipped. */
    private static class ScanResult
    {
        final List<PortfolioItem> items;
        final int placeholderCount;

        ScanResult(List<PortfolioItem> items, int placeholderCount)
        {
            this.items = items;
            this.placeholderCount = placeholderCount;
        }
    }
}

package com.runevault;

import lombok.AllArgsConstructor;
import lombok.Data;

@Data
@AllArgsConstructor
public class PortfolioItem
{
    private int itemId;
    private String itemName;
    private int quantity;
    private int buyPrice;    // 0 = unknown (e.g. bank scan)
    private String imageUrl; // nullable
    private int haPrice;     // high-alchemy value from item composition (getPrice() * 0.6)
}

package com.runevault;

import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Pricing logic for OSRS items.
 *
 * Rules (in order):
 *  1. Tradeable item          → GE market price
 *  2. Non-tradeable with parent (ItemVariationMapping) → parent's GE market price
 *  3. Non-tradeable, no parent → HA value (alch * 0.6)
 *  4. None of the above       → 0
 */
public final class PriceUtil
{
    private PriceUtil() {}

    /**
     * Returns {marketPrice, haPrice} as a two-element int array for the given canonical item ID.
     * Index 0 = buyPrice (what to store), index 1 = haPrice.
     */
    public static int[] resolvePrices(int canonicalId, ItemManager itemManager)
    {
        net.runelite.api.ItemComposition comp = itemManager.getItemComposition(canonicalId);

        // Rule 1: tradeable — use GE price. Store 0 if not cached (app uses current market
        // price as cost basis for bank items, so 0 = "unknown, treat as current market").
        if (comp.isTradeable())
        {
            int market = itemManager.getItemPrice(canonicalId);
            int ha     = (int) Math.floor(comp.getPrice() * 0.6);
            return new int[]{ market, ha };
        }

        // Rule 2: non-tradeable with a parent — use parent's GE price. Same 0-if-unknown rule.
        int parent = ItemVariationMapping.map(canonicalId);
        if (parent != canonicalId)
        {
            int market = itemManager.getItemPrice(parent);
            int ha     = (int) Math.floor(comp.getPrice() * 0.6);
            return new int[]{ market, ha };
        }

        // Rule 3: non-tradeable, no parent — try own GE price (some charged items like
        // Dragonfire shield have a cached price despite isTradeable()=false), then HA.
        int selfMarket = itemManager.getItemPrice(canonicalId);
        int ha         = (int) Math.floor(comp.getPrice() * 0.6);
        if (selfMarket > 0)
        {
            return new int[]{ selfMarket, ha };
        }
        if (ha > 0)
        {
            return new int[]{ ha, ha };
        }

        // Rule 4: nothing — zero
        return new int[]{ 0, 0 };
    }
}

package com.runevault;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.game.ItemManager;

@Slf4j
public class GETracker
{
    private static final int GE_SLOTS = 8;

    private final SupabaseClient supabase;
    private final RuneVaultConfig config;
    private final ItemManager itemManager;

    // Track previous state per slot. null = not yet seen this session (initial load).
    private final GrandExchangeOfferState[] previousStates = new GrandExchangeOfferState[GE_SLOTS];

    public GETracker(SupabaseClient supabase, RuneVaultConfig config, ItemManager itemManager)
    {
        this.supabase = supabase;
        this.config = config;
        this.itemManager = itemManager;
    }

    /** Call on logout so initial offer states are re-baselined on next login. */
    public void reset()
    {
        java.util.Arrays.fill(previousStates, null);
    }

    public void onOfferChanged(GrandExchangeOfferChanged event)
    {
        if (!config.syncGeTrades()) return;
        if (!supabase.isProfileReady()) return;

        int slot = event.getSlot();
        GrandExchangeOffer offer = event.getOffer();
        GrandExchangeOfferState state = offer.getState();

        // First time seeing this slot this session = initial load replay. Record and skip.
        if (previousStates[slot] == null)
        {
            previousStates[slot] = state;
            return;
        }

        GrandExchangeOfferState prev = previousStates[slot];
        previousStates[slot] = state;

        // Only process genuine transitions into a terminal state
        if (state == prev) return;
        if (state != GrandExchangeOfferState.BOUGHT && state != GrandExchangeOfferState.SOLD) return;

        int itemId   = offer.getItemId();
        int quantity = offer.getTotalQuantity();
        // Use the actual price paid (spent / traded), not the bid ceiling the player entered.
        // offer.getPrice() is the max-buy price; offer.getSpent() is what was actually charged.
        int price    = offer.getQuantitySold() > 0
            ? offer.getSpent() / offer.getQuantitySold()
            : offer.getPrice();

        String itemName = itemManager.getItemComposition(itemId).getName();
        String imageUrl = buildImageUrl(itemId);

        if (state == GrandExchangeOfferState.BOUGHT)
        {
            log.debug("[RuneVault] GE BUY: " + quantity + "x " + itemName + " @ " + price + "gp (actual, bid was " + offer.getPrice() + "gp)");
            supabase.upsertItem(new PortfolioItem(itemId, itemName, quantity, price, imageUrl, 0));
        }
        else
        {
            log.debug("[RuneVault] GE SELL: " + quantity + "x " + itemName);
            supabase.decrementItem(itemId, quantity);
        }
    }

    private String buildImageUrl(int itemId)
    {
        return "https://static.runelite.net/cache/item/icon/" + itemId + ".png";
    }
}

package com.runevault;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.game.ItemManager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
public class InventoryTracker
{
    private static final int COINS_ID = 995;

    private final SupabaseClient supabase;
    private final RuneVaultConfig config;
    private final ItemManager itemManager;

    // Snapshot of the last known inventory: itemId → quantity
    private final Map<Integer, Integer> lastInventory = new HashMap<>();

    // True until the first container event after login — that event is baseline, not a change
    private boolean initialLoad = true;

    // Track if the next inventory change was caused by a ground pickup ("Take")
    private boolean pendingPickup = false;
    private int pendingPickupItemId = -1;

    // Track if the next inventory change was caused by a drop action
    private boolean pendingDrop = false;
    private int pendingDropItemId = -1;

    // Last known equipment snapshot — used to avoid redundant re-uploads
    private final Map<Integer, Integer> lastEquipment = new HashMap<>();

    public InventoryTracker(SupabaseClient supabase, RuneVaultConfig config, ItemManager itemManager)
    {
        this.supabase = supabase;
        this.config = config;
        this.itemManager = itemManager;
    }

    /**
     * Call this on MenuOptionClicked to flag intentional drops before the
     * inventory change event fires.
     */
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!config.trackDropsAndSales()) return;

        if ("Drop".equalsIgnoreCase(event.getMenuOption()))
        {
            pendingDrop = true;
            pendingDropItemId = event.getItemId();
        }

        if ("Take".equalsIgnoreCase(event.getMenuOption()))
        {
            pendingPickup = true;
            pendingPickupItemId = event.getItemId();
        }
    }

    /**
     * Main inventory diff — fires on every inventory change.
     * Also handles equipment container changes to keep the equipped-items snapshot current.
     */
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.EQUIPMENT.getId())
        {
            syncEquipment(event.getItemContainer());
            return;
        }

        if (event.getContainerId() != InventoryID.INVENTORY.getId()) return;

        ItemContainer container = event.getItemContainer();
        if (container == null) return;

        Map<Integer, Integer> currentInventory = buildMap(container);

        // First event after login = initial load. Just capture as baseline, don't diff.
        if (initialLoad)
        {
            lastInventory.putAll(currentInventory);
            initialLoad = false;
            return;
        }

        // Diff: what was added?
        for (Map.Entry<Integer, Integer> entry : currentInventory.entrySet())
        {
            int itemId = entry.getKey();
            int currentQty = entry.getValue();
            int previousQty = lastInventory.getOrDefault(itemId, 0);
            int delta = currentQty - previousQty;

            if (delta > 0)
            {
                handleItemAdded(itemId, delta);
            }
        }

        // Diff: what was removed?
        for (Map.Entry<Integer, Integer> entry : lastInventory.entrySet())
        {
            int itemId = entry.getKey();
            int previousQty = entry.getValue();
            int currentQty = currentInventory.getOrDefault(itemId, 0);
            int delta = previousQty - currentQty;

            if (delta > 0)
            {
                handleItemRemoved(itemId, delta);
            }
        }

        // Update snapshot
        lastInventory.clear();
        lastInventory.putAll(currentInventory);

        // Reset action flags
        pendingPickup = false;
        pendingPickupItemId = -1;
        pendingDrop = false;
        pendingDropItemId = -1;
    }

    private void handleItemAdded(int itemId, int quantity)
    {
        if (!supabase.isProfileReady()) return;
        // Cash: only track explicit ground pickups (pendingPickup flag set by "Take" click).
        // All other coin increases (GE collection, bank withdrawal, etc.) are handled by BankTracker.
        if (itemId == COINS_ID)
        {
            // Ground pickups: pendingPickup is set by "Take" click.
            // getItemId() returns -1 for ground items so we don't check the ID here.
            if (config.syncCash() && pendingPickup)
                supabase.adjustCash(quantity);
            return;
        }

        if (!config.trackPickups()) return;

        // Only count genuine ground pickups (preceded by a "Take" click).
        // This prevents GE collections, bank withdrawals, etc. from being double-counted.
        // pendingPickupItemId is -1 for ground items (loot piles) — skip ID check in that case.
        if (!pendingPickup) return;
        if (pendingPickupItemId != -1 && pendingPickupItemId != itemId) return;

        int canonicalId = itemManager.canonicalize(itemId);
        if (canonicalId <= 0) return;
        String itemName = itemManager.getItemComposition(canonicalId).getName();
        String imageUrl = buildImageUrl(canonicalId);
        log.debug("[RuneVault] Picked up: " + quantity + "x " + itemName);

        // Buy price unknown for pickups — set to 0.
        // Route to increment_pickup_item so the 0gp does not pollute a real
        // weighted-average cost basis on an existing purchase row.
        PortfolioItem item = new PortfolioItem(canonicalId, itemName, quantity, 0, imageUrl, 0);
        supabase.incrementPickupItem(item);
    }

    private void handleItemRemoved(int itemId, int quantity)
    {
        if (!supabase.isProfileReady()) return;
        // Cash: only track explicit drops. Bank deposits / spending are handled by BankTracker.
        if (itemId == COINS_ID)
        {
            if (config.syncCash() && pendingDrop && pendingDropItemId == COINS_ID)
                supabase.adjustCash(-quantity);
            return;
        }

        if (!config.trackDropsAndSales()) return;

        // Only act on explicit drops (not inventory rearrangement, equipping, etc.)
        if (pendingDrop && pendingDropItemId == itemId)
        {
            int canonicalId = itemManager.canonicalize(itemId);
            String itemName = itemManager.getItemComposition(canonicalId).getName();
            log.debug("[RuneVault] Dropped: " + quantity + "x " + itemName);
            supabase.decrementItem(canonicalId, quantity);
        }
        // Note: GE sales are handled by GETracker, not here
    }

    /**
     * Syncs the player's currently equipped items to Supabase as source="runelite_equip".
     * Only uploads when the equipment actually changes (compared to lastEquipment snapshot).
     */
    private void syncEquipment(ItemContainer container)
    {
        if (container == null) return;
        if (!supabase.isProfileReady()) return;

        Map<Integer, Integer> current = buildMap(container);

        // Skip upload if nothing changed since last sync
        if (current.equals(lastEquipment)) return;
        lastEquipment.clear();
        lastEquipment.putAll(current);

        if (current.isEmpty())
        {
            // Nothing equipped — clear any stale rows
            supabase.clearEquipmentItems();
            return;
        }

        List<PortfolioItem> items = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : current.entrySet())
        {
            int rawId = entry.getKey();
            if (rawId == COINS_ID) continue;

            int canonicalId  = itemManager.canonicalize(rawId);
            if (canonicalId <= 0) continue;

            int[] prices    = PriceUtil.resolvePrices(canonicalId, itemManager);
            int buyPrice    = prices[0];
            int haPrice     = prices[1];

            net.runelite.api.ItemComposition comp = itemManager.getItemComposition(canonicalId);
            String rawName   = comp.getName();
            String nameLower = rawName.toLowerCase();
            String name      = nameLower.endsWith(" (members)") ? rawName.substring(0, rawName.length() - 10) : rawName;
            String imageUrl  = "https://static.runelite.net/cache/item/icon/" + canonicalId + ".png";

            items.add(new PortfolioItem(canonicalId, name, entry.getValue(), buyPrice, imageUrl, haPrice));
        }

        if (!items.isEmpty())
        {
            log.debug("[RuneVault] Syncing {} equipped items", items.size());
            supabase.bulkUpsertItems(items, "runelite_equip", null);
        }
    }

    /**
     * Call when the player logs in so we get a fresh baseline.
     */
    public void reset()
    {
        lastInventory.clear();
        lastEquipment.clear();
        initialLoad = true;
        pendingPickup = false;
        pendingPickupItemId = -1;
        pendingDrop = false;
        pendingDropItemId = -1;
    }

    private Map<Integer, Integer> buildMap(ItemContainer container)
    {
        Map<Integer, Integer> map = new HashMap<>();
        for (Item item : container.getItems())
        {
            if (item.getId() <= 0) continue;
            map.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        return map;
    }

    private String buildImageUrl(int itemId)
    {
        return "https://static.runelite.net/cache/item/icon/" + itemId + ".png";
    }
}

