    /**
     * Upsert a GE-purchased item with weighted average cost.
     * Routes to the upsert_purchase_item RPC: a single SQL INSERT … ON CONFLICT
     * that merges quantity additively and recomputes buy_price as a weighted
     * average atomically. Replaces the prior fetch-then-write path that could
     * lose data under back-to-back BUYs in the same slot.
     */
    public void upsertItem(PortfolioItem item)
    {
        if (!ensureAuthenticated()) return;
        if (!hasProfile()) { log("upsertItem skipped — no profile loaded yet"); return; }

        // Capture cached identity locally to avoid TOCTOU on profile/user switch.
        final String userId    = getUserId();
        final String profileId = cachedProfileId;
        if (profileId == null) { log("upsertItem skipped — profile cleared"); return; }

        JsonObject body = new JsonObject();
        body.addProperty("p_user_id",    userId);
        body.addProperty("p_profile_id", profileId);
        body.addProperty("p_item_id",    item.getItemId());
        body.addProperty("p_game",       "osrs");
        body.addProperty("p_item_name",  item.getItemName());
        body.addProperty("p_image_url",  item.getImageUrl() != null ? item.getImageUrl() : "");
        body.addProperty("p_qty",        item.getQuantity());
        body.addProperty("p_price",      item.getBuyPrice());

        Request request = new Request.Builder()
            .url(SUPABASE_URL + "/rest/v1/rpc/upsert_purchase_item")
            .post(RequestBody.create(JSON, gson.toJson(body)))
            .addHeader("apikey",        ANON_KEY)
            .addHeader("Authorization", "Bearer " + config.authToken())
            .addHeader("Content-Type",  "application/json")
            .addHeader("Prefer",        "return=minimal")
            .build();

        executeAsync(request, "upsertItem(" + item.getItemName() + ")");
    }

