    // Bank scan — bulk upsert
    // -------------------------------------------------------------------------

    /**
     * Bulk upsert items with an explicit source and an optional callback.
     * The callback runs on the OkHttp thread after the request succeeds — use it to
     * chain dependent operations (e.g. removeItemsMissingFromBank) so they only run
     * after the upsert has landed in the DB, avoiding race conditions.
     */
    /** Max rows per upsert request. Mirrors the web cron (`snapshot-prices/route.ts`). */
    private static final int BULK_UPSERT_CHUNK_SIZE = 500;

    public void bulkUpsertItems(java.util.List<PortfolioItem> items, String source, Runnable onSuccess)
    {
        if (!ensureAuthenticated() || items.isEmpty()) return;
        if (!hasProfile()) { log("bulkUpsert skipped — profile not loaded yet"); return; }

        // Equipment snapshots always overwrite (quantity and price may change on re-equip).
        // Bank scans respect the bankOverwriteDuplicates config.
        String prefer;
        if ("runelite_equip".equals(source)) {
            prefer = "resolution=merge-duplicates,return=minimal";
        } else {
            prefer = config.bankOverwriteDuplicates()
                ? "resolution=merge-duplicates,return=minimal"
                : "resolution=ignore-duplicates,return=minimal";
        }

        // Split into chunks of BULK_UPSERT_CHUNK_SIZE and POST sequentially. Each chunk
        // chains the next via onSuccess; the caller's onSuccess fires only after the
        // LAST chunk lands. On any chunk failure executeAsync logs + drops, the chain
        // halts, and the caller's onSuccess never runs — preventing dependent work
        // (e.g. removeItemsMissingFromBank) from acting on partial bank state.
        int total = items.size();
        int chunkCount = (total + BULK_UPSERT_CHUNK_SIZE - 1) / BULK_UPSERT_CHUNK_SIZE;
        sendBulkUpsertChunk(items, source, prefer, 0, chunkCount, onSuccess);
    }

    private void sendBulkUpsertChunk(java.util.List<PortfolioItem> items, String source, String prefer,
                                     int chunkIndex, int chunkCount, Runnable finalOnSuccess)
    {
        int from = chunkIndex * BULK_UPSERT_CHUNK_SIZE;
        int to = Math.min(from + BULK_UPSERT_CHUNK_SIZE, items.size());
        java.util.List<PortfolioItem> slice = items.subList(from, to);

        String userId = getUserId();
        JsonArray body = new JsonArray();
        for (PortfolioItem item : slice)
        {
            JsonObject obj = new JsonObject();
            obj.addProperty("id",         java.util.UUID.randomUUID().toString());
            obj.addProperty("user_id",    userId);
            obj.addProperty("profile_id", cachedProfileId);
            obj.addProperty("item_id",    item.getItemId());
            obj.addProperty("item_name",  item.getItemName());
            obj.addProperty("game",       "osrs");
            obj.addProperty("quantity",   item.getQuantity());
            obj.addProperty("buy_price",  item.getBuyPrice());
            obj.addProperty("ha_price",   item.getHaPrice());
            obj.addProperty("watchlisted", false);
            obj.addProperty("source",     source);
            // Intentionally omitting last_added_at and buy_date — bank scans should not
            // update these fields on existing rows, keeping GE/pickup timestamps intact.
            if (item.getImageUrl() != null) obj.addProperty("image_url", item.getImageUrl());
            body.add(obj);
        }

        Request request = new Request.Builder()
            .url(SUPABASE_URL + "/rest/v1/portfolio_items?on_conflict=user_id,profile_id,item_id,game")
            .post(RequestBody.create(JSON, gson.toJson(body)))
            .addHeader("apikey",        ANON_KEY)
            .addHeader("Authorization", "Bearer " + config.authToken())
            .addHeader("Content-Type",  "application/json")
            .addHeader("Prefer",        prefer)
            .build();

        boolean isLastChunk = (chunkIndex + 1 == chunkCount);
        Runnable chunkOnSuccess = isLastChunk
            ? finalOnSuccess
            : () -> sendBulkUpsertChunk(items, source, prefer, chunkIndex + 1, chunkCount, finalOnSuccess);

        String label = "bulkUpsert(chunk " + (chunkIndex + 1) + "/" + chunkCount
            + ", " + slice.size() + " items, source=" + source + ")";
        executeAsync(request, label, chunkOnSuccess);
    }

