import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.ActionListener;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;

public class RuneVaultPanel extends PluginPanel
{
    private static final Color COLOR_GOLD         = new Color(0xe8, 0xa0, 0x60);
    private static final Color COLOR_CONNECTED    = new Color(0x40, 0xc0, 0x70);
    private static final Color COLOR_DISCONNECTED = new Color(0xc0, 0x50, 0x50);
    private static final Color COLOR_WARNING      = new Color(0xe0, 0xb0, 0x40);

    // Status row
    private final JLabel statusDot  = new JLabel("\u25cf"); // filled circle
    private final JLabel statusText = new JLabel("Not connected");
    private final JLabel profileLabel = new JLabel(" ");

    private String currentPlayerName = null;

    // Connect form
    private final JTextField codeField    = new JTextField();
    private final JButton    connectBtn   = new JButton("Connect");
    private final JLabel     feedbackLabel = new JLabel(" ");

    // Disconnect
    private final JButton disconnectBtn = new JButton("Disconnect");

    // Sync toggle checkboxes — stored so refreshToggles() can update them
    private JCheckBox syncGETradesBox;
    private JCheckBox trackPickupsBox;
    private JCheckBox trackDropsBox;
    private JCheckBox syncCashBox;
    private JCheckBox bankScanBox;
    private JComboBox<String> scanModeBox;

    // Privacy — read-only badge mirroring profiles.is_public from the server.
    // Visibility is controlled exclusively by the Rune Vault app; the plugin only displays.
    // Initial state is the "unknown" tri-state — until a profile is fetched, the badge
    // must not claim Public or Private. Mirrors the status row's "Not connected" idiom.
    private final JLabel visibilityDot   = new JLabel("●");
    private final JLabel visibilityLabel = new JLabel("Visibility: —");

    private final RuneVaultConfig config;
    private final java.util.function.Supplier<String>  shortIdSupplier;

    private static final Color COLOR_PUBLIC  = new Color(0x40, 0xc0, 0x70); // green dot for Public
    private static final Color COLOR_PRIVATE = new Color(0x90, 0x90, 0x90); // grey dot for Private
    private static final Color COLOR_UNKNOWN = new Color(0x55, 0x55, 0x55); // darker grey for "no profile yet"

    RuneVaultPanel(ActionListener onConnect, ActionListener onDisconnect, RuneVaultConfig config,
                   java.util.function.Supplier<String> shortIdSupplier)
    {
        this.config          = config;
        this.shortIdSupplier = shortIdSupplier;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 10, 10, 10));

        // Allow pressing Enter in the code field to trigger connect
        codeField.addKeyListener(new KeyAdapter()
        {
            @Override
            public void keyPressed(KeyEvent e)
            {
                if (e.getKeyCode() == KeyEvent.VK_ENTER) onConnect.actionPerformed(null);
            }
        });

        connectBtn.addActionListener(onConnect);
        disconnectBtn.addActionListener(onDisconnect);

        add(buildContent(), BorderLayout.NORTH);
    }

