        connectCard.setLayout(new BoxLayout(connectCard, BoxLayout.Y_AXIS));

        JLabel codeLabel = new JLabel("Link Code");
        codeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        codeLabel.setFont(FontManager.getRunescapeSmallFont());
        codeLabel.setAlignmentX(LEFT_ALIGNMENT);
        connectCard.add(codeLabel);
        connectCard.add(Box.createVerticalStrut(4));

        codeField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        codeField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        codeField.setForeground(Color.WHITE);
        codeField.setCaretColor(Color.WHITE);
        codeField.setFont(new Font("Monospaced", Font.BOLD, 15));
        codeField.setHorizontalAlignment(JTextField.CENTER);
        codeField.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            new EmptyBorder(4, 6, 4, 6)
        ));
        codeField.setAlignmentX(LEFT_ALIGNMENT);
        connectCard.add(codeField);
        connectCard.add(Box.createVerticalStrut(6));

        styleButton(connectBtn, COLOR_GOLD, new Color(0x1a, 0x0a, 0x00));
        connectBtn.setAlignmentX(LEFT_ALIGNMENT);
        connectBtn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        connectCard.add(connectBtn);

        feedbackLabel.setFont(FontManager.getRunescapeSmallFont());
        feedbackLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        feedbackLabel.setAlignmentX(LEFT_ALIGNMENT);
        feedbackLabel.setBorder(new EmptyBorder(4, 0, 0, 0));
        connectCard.add(feedbackLabel);

        root.add(connectCard);
        root.add(Box.createVerticalStrut(8));

        // ── Disconnect button ────────────────────────────────────────────────
        styleButton(disconnectBtn, new Color(0x55, 0x15, 0x15), new Color(0xff, 0x88, 0x88));
        disconnectBtn.setAlignmentX(LEFT_ALIGNMENT);
        disconnectBtn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        disconnectBtn.setVisible(false);
        root.add(disconnectBtn);

        // ── Sync toggles ─────────────────────────────────────────────────────
        root.add(Box.createVerticalStrut(8));
        root.add(buildSyncCard());

        // ── Open portfolio in browser ─────────────────────────────────────────
        root.add(Box.createVerticalStrut(8));
        JButton openWebBtn = new JButton("\uD83C\uDF10  Open Portfolio");
        styleButton(openWebBtn, new Color(0x25, 0x25, 0x25), new Color(0xa0, 0xa0, 0xa0));
        openWebBtn.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            new EmptyBorder(4, 8, 4, 8)
        ));
        openWebBtn.setBorderPainted(true);
        openWebBtn.setAlignmentX(LEFT_ALIGNMENT);
        openWebBtn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        openWebBtn.addActionListener(e -> {
            // Canonical portfolio URL is /u/{shortId}/{slug}. The web app 301-redirects when
            // the slug differs from the profile's current rs_username, so passing the in-game
            // name is safe — capitalization/spaces are normalized server-side.
            String shortId = shortIdSupplier != null ? shortIdSupplier.get() : null;
            String url;
            if (shortId != null && currentPlayerName != null)
            {
                String slug;
                try { slug = java.net.URLEncoder.encode(currentPlayerName, "UTF-8"); }
                catch (java.io.UnsupportedEncodingException ex) { slug = currentPlayerName.replace(" ", "%20"); }
                url = "https://runevault.vaultek.co/u/" + shortId + "/" + slug;
            }
            else
            {
                url = "https://runevault.vaultek.co";
            }
            LinkBrowser.browse(url);
        });
        root.add(openWebBtn);

        // ── Hint ─────────────────────────────────────────────────────────────
        root.add(Box.createVerticalStrut(12));
        JLabel hint = new JLabel("<html><body style='color:#888;width:160px'>"
            + "Generate a code in the Rune Vault app under Settings \u2192 Connect RuneLite Plugin."
            + "</body></html>");
        hint.setFont(FontManager.getRunescapeSmallFont());
        hint.setAlignmentX(LEFT_ALIGNMENT);
        root.add(hint);

        return root;
    }

    private JPanel buildSyncCard()
    {
        JPanel card = buildCard();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));

        JLabel heading = new JLabel("SYNC SETTINGS");
        heading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        heading.setFont(FontManager.getRunescapeSmallFont());
        heading.setAlignmentX(LEFT_ALIGNMENT);
        card.add(heading);
        card.add(Box.createVerticalStrut(6));

        syncGETradesBox  = addToggle(card, "GE Trades",     config.syncGeTrades(),      v -> config.setSyncGeTrades(v));
        card.add(Box.createVerticalStrut(3));
        trackPickupsBox  = addToggle(card, "Item Pickups",  config.trackPickups(),       v -> config.setTrackPickups(v));
        card.add(Box.createVerticalStrut(3));
        trackDropsBox    = addToggle(card, "Drops & Sales", config.trackDropsAndSales(), v -> config.setTrackDropsAndSales(v));
        card.add(Box.createVerticalStrut(3));
        syncCashBox      = addToggle(card, "Cash Stack",    config.syncCash(),           v -> config.setSyncCash(v));
        card.add(Box.createVerticalStrut(3));
        bankScanBox      = addToggle(card, "Bank Scan",     config.bankScanEnabled(),    v -> config.setBankScanEnabled(v));
        card.add(Box.createVerticalStrut(3));

        // Scan Mode dropdown — only relevant when bank scan is on
        JPanel scanModeRow = new JPanel(new BorderLayout(6, 0));
        scanModeRow.setOpaque(false);
        scanModeRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
        scanModeRow.setAlignmentX(LEFT_ALIGNMENT);
        JLabel scanModeLabel = new JLabel("  Scan Mode");
        scanModeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        scanModeLabel.setFont(FontManager.getRunescapeSmallFont());
        scanModeBox = new JComboBox<>(new String[]{"Prompt", "Auto"});
        scanModeBox.setSelectedItem(config.bankScanMode() == BankScanMode.AUTO ? "Auto" : "Prompt");
        scanModeBox.setFont(FontManager.getRunescapeSmallFont());
        scanModeBox.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        scanModeBox.setForeground(Color.WHITE);
        scanModeBox.setMaximumSize(new Dimension(80, 20));
        scanModeBox.addActionListener(e -> config.setBankScanMode(
            "Auto".equals(scanModeBox.getSelectedItem()) ? BankScanMode.AUTO : BankScanMode.PROMPT));
        scanModeRow.add(scanModeLabel, BorderLayout.CENTER);
        scanModeRow.add(scanModeBox,   BorderLayout.EAST);
        card.add(scanModeRow);

        // ── Privacy divider ───────────────────────────────────────────────────
        card.add(Box.createVerticalStrut(8));
        JSeparator sep = new JSeparator();
        sep.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
        sep.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        sep.setAlignmentX(LEFT_ALIGNMENT);
        card.add(sep);
        card.add(Box.createVerticalStrut(6));

        JLabel privacyHeading = new JLabel("PRIVACY");
        privacyHeading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        privacyHeading.setFont(FontManager.getRunescapeSmallFont());
        privacyHeading.setAlignmentX(LEFT_ALIGNMENT);
        card.add(privacyHeading);
        card.add(Box.createVerticalStrut(4));

        // Read-only visibility badge — the app owns is_public, the plugin only mirrors it.
        JPanel visibilityRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 5, 0));
        visibilityRow.setOpaque(false);
        visibilityRow.setAlignmentX(LEFT_ALIGNMENT);
        visibilityRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
        visibilityDot.setFont(new Font("Monospaced", Font.PLAIN, 13));
        visibilityDot.setForeground(COLOR_UNKNOWN);
        visibilityLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        visibilityLabel.setFont(FontManager.getRunescapeSmallFont());
        visibilityRow.add(visibilityDot);
        visibilityRow.add(visibilityLabel);
        card.add(visibilityRow);
        card.add(Box.createVerticalStrut(2));

        JLabel visibilityHint = new JLabel("<html><body style='color:#888;width:160px'>"
            + "Manage privacy in the Rune Vault app → Settings."
            + "</body></html>");
        visibilityHint.setFont(FontManager.getRunescapeSmallFont());
        visibilityHint.setAlignmentX(LEFT_ALIGNMENT);
        card.add(visibilityHint);

        return card;
    }

    /** Builds a toggle row, adds it to the parent panel, and returns the checkbox for later updates. */
    private JCheckBox addToggle(JPanel parent, String label, boolean initialValue, java.util.function.Consumer<Boolean> onToggle)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
        row.setAlignmentX(LEFT_ALIGNMENT);

        JLabel lbl = new JLabel(label);
        lbl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        lbl.setFont(FontManager.getRunescapeSmallFont());

        JCheckBox box = new JCheckBox();
        box.setSelected(initialValue);
        box.setOpaque(false);
        box.setFocusPainted(false);
        box.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        box.addActionListener(e -> onToggle.accept(box.isSelected()));

        row.add(lbl, BorderLayout.CENTER);
        row.add(box, BorderLayout.EAST);
        parent.add(row);
        return box;
    }

    /**
     * Re-syncs all toggle checkboxes from the live config values.
     * Call this whenever config may have changed externally (e.g. via the config panel).
     */
    public void refreshToggles(RuneVaultConfig config)
    {
        SwingUtilities.invokeLater(() ->
        {
            if (syncGETradesBox != null) syncGETradesBox.setSelected(config.syncGeTrades());
            if (trackPickupsBox != null) trackPickupsBox.setSelected(config.trackPickups());
            if (trackDropsBox   != null) trackDropsBox  .setSelected(config.trackDropsAndSales());
            if (syncCashBox     != null) syncCashBox    .setSelected(config.syncCash());
            if (bankScanBox     != null) bankScanBox    .setSelected(config.bankScanEnabled());
            if (scanModeBox     != null) scanModeBox    .setSelectedItem(config.bankScanMode() == BankScanMode.AUTO ? "Auto" : "Prompt");
        });
    }

    /**
     * Repaint the visibility badge to mirror the server-side is_public.
     * Called from SupabaseClient on initial fetch, Realtime UPDATE, and disconnect.
     * Pass null for the "unknown" tri-state (no profile fetched yet / disconnected) —
     * the badge then shows a neutral dot + "Visibility: —" so the plugin doesn't
     * falsely claim Public or Private before reading the actual server value.
     */
    public void refreshVisibility(Boolean isPublic)
    {
        SwingUtilities.invokeLater(() ->
        {
            if (isPublic == null)
            {
                visibilityDot.setForeground(COLOR_UNKNOWN);
                visibilityLabel.setText("Visibility: —");
                return;
            }
            visibilityDot.setForeground(isPublic ? COLOR_PUBLIC : COLOR_PRIVATE);
            visibilityLabel.setText(isPublic ? "Visibility: Public" : "Visibility: Private");
        });
    }

    private JPanel buildCard()
    {
        JPanel card = new JPanel();
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            new EmptyBorder(8, 8, 8, 8)
        ));
        card.setAlignmentX(LEFT_ALIGNMENT);
        card.setMaximumSize(new Dimension(Integer.MAX_VALUE, Short.MAX_VALUE));
        return card;
    }

    private void styleButton(JButton btn, Color bg, Color fg)
    {
        btn.setBackground(bg);
        btn.setForeground(fg);
        btn.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        btn.setFocusPainted(false);
        btn.setBorderPainted(false);
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.setOpaque(true);
    }

    // -------------------------------------------------------------------------
    // State update API — all methods are EDT-safe
    // -------------------------------------------------------------------------

    /** Returns the code the user typed, trimmed and uppercased. */
    public String getCode()
    {
        return codeField.getText().trim().toUpperCase();
    }

    public void setConnecting()
    {
        SwingUtilities.invokeLater(() ->
        {
            statusDot.setForeground(COLOR_WARNING);
            statusText.setText("Connecting\u2026");
            connectBtn.setEnabled(false);
            connectBtn.setText("Connecting\u2026");
            feedbackLabel.setText(" ");
            feedbackLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        });
    }

    public void setConnected(String playerName)
    {
        currentPlayerName = (playerName != null && !playerName.isEmpty()) ? playerName : null;
        SwingUtilities.invokeLater(() ->
        {
            statusDot.setForeground(COLOR_CONNECTED);
            statusText.setText("Connected");
            profileLabel.setText(currentPlayerName != null
                ? "Playing as: " + currentPlayerName : " ");
            codeField.setText("");
            connectBtn.setEnabled(true);
            connectBtn.setText("Re-link");
            feedbackLabel.setText(" ");
            disconnectBtn.setVisible(true);
        });
    }

    public void setDisconnected()
    {
        currentPlayerName = null;
        SwingUtilities.invokeLater(() ->
        {
            statusDot.setForeground(COLOR_DISCONNECTED);
            statusText.setText("Not connected");
            profileLabel.setText(" ");
            connectBtn.setEnabled(true);
            connectBtn.setText("Connect");
            feedbackLabel.setText(" ");
            disconnectBtn.setVisible(false);
            // Reset the visibility badge to the unknown tri-state — there's no active
            // profile, so we must not keep showing the previous Public/Private.
            visibilityDot.setForeground(COLOR_UNKNOWN);
            visibilityLabel.setText("Visibility: —");
        });
    }

    public void setFeedback(String message, boolean isError)
    {
        SwingUtilities.invokeLater(() ->
        {
            if (isError)
            {
                statusDot.setForeground(COLOR_DISCONNECTED);
                statusText.setText("Not connected");
            }
            feedbackLabel.setForeground(isError ? COLOR_DISCONNECTED : COLOR_CONNECTED);
            feedbackLabel.setText(message);
            connectBtn.setEnabled(true);
            connectBtn.setText(isError ? "Connect" : "Re-link");
        });
    }

    public void updatePlayerName(String playerName)
    {
        currentPlayerName = (playerName != null && !playerName.isEmpty()) ? playerName : currentPlayerName;
        SwingUtilities.invokeLater(() ->
            profileLabel.setText(currentPlayerName != null
                ? "Playing as: " + currentPlayerName : " ")
        );
    }

    // -------------------------------------------------------------------------
    // Nav icon — a simple 16x16 gold "RV" badge
    // -------------------------------------------------------------------------

    public static java.awt.image.BufferedImage buildNavIcon()
    {
        java.awt.image.BufferedImage img =
            new java.awt.image.BufferedImage(16, 16, java.awt.image.BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        // Fill background with toolbar colour so there are no alpha-composite smudges
        g.setColor(new Color(0x3b, 0x3b, 0x3b));
        g.fillRect(0, 0, 16, 16);
        g.setColor(new Color(0xe8, 0xa0, 0x60));
        g.fillRoundRect(0, 0, 16, 16, 5, 5);
        g.setColor(new Color(0x1a, 0x0a, 0x00));
        g.setFont(new Font("Dialog", Font.BOLD, 8));
        FontMetrics fm = g.getFontMetrics();
        String text = "RV";
        g.drawString(text, (16 - fm.stringWidth(text)) / 2, (16 + fm.getAscent() - fm.getDescent()) / 2);
        g.dispose();
        return img;
    }
}

package com.runevault;

public enum BankScanMode
{
    PROMPT("Prompt"),
    AUTO("Auto");

    private final String label;

    BankScanMode(String label)
    {
        this.label = label;
    }

    @Override
    public String toString()
    {
        return label;
    }
}
